function list(items){return items?`<ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}
function table(rows){return `<div class="table-wrap"><table>${rows.map((r,i)=>`<tr>${r.map(c=>i===0?`<th>${c}</th>`:`<td>${c}</td>`).join('')}</tr>`).join('')}</table></div>`}
function diagram(type){
 if(type==='boot') return `<div class="diagram"><div class="diagram-title">LEGACY BIOS + MBR BOOT (SIMPLIFIED)</div><div class="diagram-flow"><span>Power on</span><b>→</b><span>BIOS firmware<br><small>hardware initialization</small></span><b>→</b><span>Disk LBA 0<br><small>MBR boot code</small></span><b>→</b><span>Active partition<br><small>volume boot code</small></span><b>→</b><span>OS bootloader</span><b>→</b><span>OS kernel<br><small>loaded into RAM</small></span></div><div class="diagram-foot">UEFI/GPT is a different path: firmware Boot Manager reads NVRAM boot options and launches an EFI application from the EFI System Partition. It does not execute legacy MBR boot code.</div></div>`;
 if(type==='signage') return `<div class="diagram"><div class="diagram-title">SIMPLIFIED DIGITAL SIGNAGE ARCHITECTURE</div><div class="architecture"><div class="arch-box">Advertiser /<br>Content owner</div><b>→</b><div class="arch-box">CMS portal<br><small>users · schedules · playlists</small></div><b>→</b><div class="arch-box">Distribution<br>platform / cloud</div><b>→</b><div class="arch-box">Network<br><small>WAN / VPN / Internet</small></div><b>→</b><div class="arch-box">Media player<br><small>OS / app / cache</small></div><b>→</b><div class="arch-box highlight">LED processor<br>and display</div></div><div class="diagram-foot">Actual deployments vary. Some systems use local scheduling, edge servers, cellular links or vendor-specific controllers. This diagram is conceptual, not a claim about the exact architecture in the 26 July incident.</div></div>`;
 if(type==='attack') return `<div class="diagram"><div class="diagram-title">POTENTIAL ATTACK SURFACES — INVESTIGATIVE HYPOTHESES</div><div class="attack-map"><div class="safe-box">External actor<br><small>identity not established</small></div><div class="down-arrow">↓</div><div class="attack-branches"><span>Compromised account</span><span>Web / CMS vulnerability</span><span>Exposed management API</span><span>Hosting / supply chain</span></div><div class="down-arrow">↓</div><div class="risk-box">CMS / publishing service<br><small>hypothetical central control point</small></div><div class="down-arrow">↓</div><div class="impact-box">Unauthorized playlist or media<br>↓<br>Connected media players / displays</div></div><div class="diagram-foot">These are common investigation hypotheses only. Public reporting does not establish which path, if any, was used in this incident.</div></div>`;
 return '';
}
const root=document.querySelector('#tasks');
root.innerHTML=tasks.map(t=>`<article class="task" id="task-${t.n}"><button class="task-toggle" aria-expanded="false"><span class="task-num">${t.n}</span><span class="task-heading"><span class="task-badge">${t.badge}</span><span class="task-title">${t.title}</span><span class="task-sub">${t.sub}</span></span><span class="chev">⌄</span></button><div class="task-body"><div class="detail-intro"><span>RESEARCH FILE ${t.n}</span><span>Evidence-led analysis · English</span></div><div class="detail-grid">${t.sections.map((s,i)=>`<section class="detail ${s.table||s.diagram||s.h.startsWith('Case overview')?'full':''}"><h3>${s.h}</h3>${s.p?`<p>${s.p}</p>`:''}${s.diagram?diagram(s.diagram):''}${s.table?table(s.table):''}${list(s.items)}</section>`).join('')}</div></div></article>`).join('');
function setCard(card,open){card.classList.toggle('open',open);card.querySelector('.task-toggle').setAttribute('aria-expanded',String(open));}
root.querySelectorAll('.task-toggle').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.task');setCard(card,!card.classList.contains('open'));}));
document.querySelector('#expandAll').addEventListener('click',()=>root.querySelectorAll('.task').forEach(c=>setCard(c,true)));
document.querySelector('#collapseAll').addEventListener('click',()=>root.querySelectorAll('.task').forEach(c=>setCard(c,false)));
document.querySelector('#sourceList').innerHTML=sourceData.map((s,i)=>`<article class="source-item"><span class="source-index">${String(i+1).padStart(2,'0')}</span><div><b>${s[0]}</b><p>${s[1]}</p><small>${s[3]}</small></div><a href="${s[2]}" target="_blank" rel="noopener noreferrer">Open source ↗</a></article>`).join('');


// Theme controls: Black (default), Dark and Light. Preference is saved locally.
const themeButtons = document.querySelectorAll('[data-theme-choice]');
function applyTheme(theme){
  const valid = ['black','dark','light'].includes(theme) ? theme : 'black';
  if(valid === 'black') document.body.removeAttribute('data-theme');
  else document.body.setAttribute('data-theme', valid);
  themeButtons.forEach(button => button.setAttribute('aria-pressed', String(button.dataset.themeChoice === valid)));
  try { localStorage.setItem('df-portfolio-theme', valid); } catch(e) {}
}
let savedTheme = 'black';
try { savedTheme = localStorage.getItem('df-portfolio-theme') || 'black'; } catch(e) {}
applyTheme(savedTheme);
themeButtons.forEach(button => button.addEventListener('click', () => applyTheme(button.dataset.themeChoice)));
